"""OBSOLETE (7 Oct 2026): Experiment 3 (text generated by Claude Haiku 4.5) was removed from the paper; kept for the record, not run by run_all.sh.
Write the Experiment 3 block (\\resThree*) of paper/results_macros.tex from results/summary_exp3.json (exp3_llm.py),
results/exp3_diagnostics.json (exp3_diagnostics.py) and the usage file of the model-X regenerations.
Usage: python experiments/exp3_macros.py [--write]   (without --write the block is printed only)"""
import sys, json, argparse, math, re; from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import numpy as np, pandas as pd
from citext.paths import RESULTS_DIR, PAPER_DIR
MACROS_TEX = PAPER_DIR / "results_macros.tex"
BEGIN, END = "% ---------- Experiment 3 ----------", "% ---------- Application (CMV) ----------"
CRT_USAGE = Path.home() / ".cache/ci_text/llm/crt_claude-haiku-4-5_n500_B19.usage.json"
MODEL_NAMES = {"claude-haiku-4-5": "Claude Haiku 4.5"}
E1_VIEWS = ["E1+S", "E1+L300", "E1+S+L300", "E1c", "E1c+S+L300"]   # views built from E1 ("Adding ... to E1 leaves rho ...")
E1_BASED = ["E1", "E1+E2"] + E1_VIEWS                                  # views containing E1: the R^2 range for the summary side


def rng_phrase(lo, hi, nd=2):
    a, b = f"{lo:.{nd}f}", f"{hi:.{nd}f}"
    return f"at about {a}" if a == b else f"between {a} and {b}"


def block():
    S = json.load(open(RESULTS_DIR / "summary_exp3.json")); D = json.load(open(RESULTS_DIR / "exp3_diagnostics.json"))
    P1 = S["primary_regressor"]; full = pd.DataFrame(S["full_sample"]); sub = pd.DataFrame(S["subsample"])
    sf = S["sentiment_following"]; crt = D["crt"]; views = D["views"]; bench = D["benchmarks_from_E1"]; subsets = D["subsets"]
    crt_cost = json.load(open(CRT_USAGE)).get("cost_usd", float("nan")) if CRT_USAGE.exists() else float("nan")

    def fs(axis, hyp, psi, col):
        return float(full[(full.axis == axis) & (full.hyp == hyp) & (full.psi == psi) & (full.reg == P1)][col].iloc[0])

    e1_trunc = next(iter(D["truncation"].values()))
    m = [
        ("resThreeModel", MODEL_NAMES.get(S["model"], S["model"])), ("resThreeTemp", f"{float(re.search(r'[0-9.]+', str(S['temperature'])).group()):g}"), ("resThreeN", str(S["n_rows"])),
        ("resThreeCost", f"{S['usage']['cost_usd']:.1f}"), ("resThreeCRTcost", f"{crt_cost:.1f}"),
        ("resThreeLabelCorrAlt", f"{sf['corr_label_B1']:.2f}"), ("resThreeLabelCorrNull", f"{sf['corr_label_B0']:.2f}"),
        ("resThreeTruncFrac", f"{100 * e1_trunc['frac_over_256']:.1f}\\%"),
        ("resThreeRhoEone", f"{fs('sentiment', 'H0', 'E1', 'rho_hat'):.3f}"), ("resThreeSeEone", f"{fs('sentiment', 'H0', 'E1', 'se'):.3f}"),
        ("resThreeRhoEtwo", f"{fs('sentiment', 'H0', 'E2', 'rho_hat'):.3f}"), ("resThreeRhoBoth", f"{fs('sentiment', 'H0', 'E1+E2', 'rho_hat'):.3f}"),
        ("resThreeRValpha", f"{fs('sentiment', 'H0', 'E1', 'RV_alpha'):.2f}"),
        ("resThreeLCsmall", f"{min((c for c in D['learning_curve'] if c['hyp'] == 'H0' and c['psi'] == 'E1'), key=lambda c: c['n'])['med']:.2f}"),
        ("resThreeLClarge", f"{fs('sentiment', 'H0', 'E1', 'rho_hat'):.2f}"),
        ("resThreeMargNull", f"{sf['corr_A_B0']:.2f}"), ("resThreeMargAlt", f"{sf['corr_A_B1']:.2f}"), ("resThreeRhoAlt", f"{fs('sentiment', 'H1', 'E1', 'rho_hat'):.2f}"),
        ("resThreeBenchOneTwo", f"{fs('sentiment', 'H0', 'E1', 'bench'):.3f}"), ("resThreeBenchTwoOne", f"{fs('sentiment', 'H0', 'E2', 'bench'):.3f}"),
        ("resThreeCRTn", str(crt["n_sub"])), ("resThreeCRTB", str(crt["B"])), ("resThreeCRTmean", f"{crt['rho_draws_mean']:.2f}"), ("resThreeCRTsd", f"{crt['rho_draws_sd']:.3f}"),
        ("resThreeCRTobs", f"{crt['rho_obs']:.3f}"), ("resThreeCRTp", f"{crt['p_crt']:.2f}"), ("resThreeCRTband", f"{1.96 * crt['se_obs']:.2f}"),
        ("resThreeShortN", str(subsets["short_posts_fit_in_window"]["n"])), ("resThreeShortRho", f"{subsets['short_posts_fit_in_window']['rho_hat']:.3f}"),
        ("resThreeShortSe", f"{subsets['short_posts_fit_in_window']['se']:.3f}"),
        ("resThreeLongN", str(subsets["long_posts_truncated"]["n"])), ("resThreeLongRho", f"{subsets['long_posts_truncated']['rho_hat']:.2f}"),
        ("resThreeViewsRhoRange", rng_phrase(min(views[v]['rho_hat'] for v in E1_VIEWS), max(views[v]['rho_hat'] for v in E1_VIEWS))),
        ("resThreeRhoEoneKRR", f"{float(full[(full.axis == 'sentiment') & (full.hyp == 'H0') & (full.psi == 'E1') & (full.reg == S['secondary_regressor'])].rho_hat.iloc[0]):.3f}"),
        ("resThreeRhoEtwoKRR", f"{float(full[(full.axis == 'sentiment') & (full.hyp == 'H0') & (full.psi == 'E2') & (full.reg == S['secondary_regressor'])].rho_hat.iloc[0]):.3f}"),
        ("resThreeRtwoBEtwo", f"{views['E2']['R2_B']:.2f}"), ("resThreeRtwoBEone", f"{views['E1']['R2_B']:.2f}"),
        ("resThreeViewsBenchMax", f"{max(b['rho_bench'] for b in bench.values()):.3f}"),
        ("resThreeRtwoAviews", f"{math.ceil(10 * max(v['R2_A'] for v in views.values())) / 10:g}"),
        ("resThreePConeRho", f"{fs('pc1', 'H0', 'E1', 'rho_hat'):.2f}"), ("resThreePConeRhoEtwo", f"{fs('pc1', 'H0', 'E2', 'rho_hat'):.2f}"),
        ("resThreeRtwoBviews", rng_phrase(min(views[v]['R2_B'] for v in E1_BASED), max(views[v]['R2_B'] for v in E1_BASED))),
    ]
    lines = [BEGIN, f"% written by code/experiments/exp3_macros.py from results/summary_exp3.json and exp3_diagnostics.json (primary regressor: {P1}); do not edit by hand"]
    lines += ["\\newcommand{\\%s}{%s}" % (k, v) for k, v in m]
    return "\n".join(lines) + "\n"


def main():
    ap = argparse.ArgumentParser(); ap.add_argument("--write", action="store_true"); args = ap.parse_args()
    new = block(); print(new)
    if args.write:
        s = MACROS_TEX.read_text(); i, j = s.index(BEGIN), s.index(END)
        MACROS_TEX.write_text(s[:i] + new + s[j:]); print("written to", MACROS_TEX)


if __name__ == "__main__":
    main()
